export default function buttons(){
    const teaName = ['Earl Greay', 'Mango & Black'];
    const teaPicture = ['https://i.imgur.com/M5d7VHF.png', 'https://i.imgur.com/BMlU1Fg.png'];

    return(
        <div>
            {teaName.map((name, index) => (
                <button>
                    {/* {name} */}
                    <img src={teaPicture[index]} />
                </button>
            ))}
        </div>
    );
}
